import fs from "node:fs";
import path from "node:path";
import postcss from "postcss";
import { classesDefinedIn, extractCss, hitKey, type CssSource } from "./css-extract";
import { allClassesInSelector } from "./selectors";
import { buildTokens, GLOBALS_FILE, type TokenNotes } from "./tokens";

/**
 * Builds every generated file of docs/design-system/ from the repository and
 * returns them as text (#1773). `sync.ts` writes them; `--check` compares them
 * with what is on disk. Nothing here writes, and nothing in the output depends
 * on the date, a commit or an absolute path.
 */

export const SYNC_COMMAND = "npm run design-system:sync";
export const SYSTEM_DIR = "docs/design-system";
export const SOURCE_DIR = "scripts/design-system";
export const PREFLIGHT_FILE = "node_modules/tailwindcss/preflight.css";
const LAYERED_FILES: Record<string, string> = { [PREFLIGHT_FILE]: "base" };

export interface CssSpec {
  file: string;
  classes?: string[];
  selectors?: string[];
  /** Classes whose descendant rules are kept too (`.report-table th`); see css-extract.ts. */
  scopes?: string[];
  /** Keep every rule of the file (for a stylesheet with no classes to match, such as the Tailwind reset). */
  all?: boolean;
}

export interface PartSpec {
  name: string;
  group?: string;
  /** Repository path of the README source; absent for a part with none (the gallery cover) or a shared CSS entry. */
  readme?: string;
  /** False for a shared CSS entry that has no preview of its own, such as Base. */
  preview?: boolean;
  css: CssSpec[];
}

export interface Manifest {
  groups: string[];
  parts: PartSpec[];
}

export interface BuildResult {
  /** Repository path to file text, for every generated file. */
  files: Map<string, string>;
  problems: string[];
  /** Base value of every token, for comparing with an older copy. */
  tokenValues: Record<string, string>;
}

type ReadFile = (relativePath: string) => string | undefined;

const generatedHeader = (sources: string[]) => `Generated by ${SYNC_COMMAND} from ${sources.join(", ")}. Do not edit by hand.`;

export function escapeHtml(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/** The first paragraph of a README as inline HTML: `code` and **bold** only. */
export function firstParagraphHtml(markdown: string): string {
  const lines: string[] = [];
  for (const line of markdown.split("\n")) {
    if (line.trim() === "") {
      if (lines.length > 0) break;
      continue;
    }
    if (lines.length === 0 && /^(#|<!--)/.test(line)) continue;
    lines.push(line.trim());
  }
  return escapeHtml(lines.join(" "))
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
}

export interface PreviewParts {
  height: number | undefined;
  group: string | undefined;
  body: string;
}

/** Split a preview into its `@dsCard` header and the markup after it. */
export function parsePreview(html: string): PreviewParts {
  const match = /^<!--\s*@dsCard\b([^>]*?)-->\s*\n?/.exec(html);
  const header = match?.[1] ?? "";
  const height = /height=(\d+)/.exec(header)?.[1];
  const group = /group="([^"]*)"/.exec(header)?.[1];
  return { height: height ? Number(height) : undefined, group, body: match ? html.slice(match[0].length).replace(/\s+$/, "") : html.replace(/\s+$/, "") };
}

function stripForClassScan(html: string): { markup: string; styles: string[] } {
  const styles: string[] = [];
  const markup = html
    .replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gi, (_, css: string) => {
      styles.push(css);
      return "";
    })
    .replace(/<!--[\s\S]*?-->/g, "");
  return { markup, styles };
}

/** Classes a preview's markup uses, and the `var(--x)` names it reads without a fallback. */
export function previewUsage(html: string): { classes: string[]; ownClasses: Set<string>; variables: string[]; ownVariables: Set<string> } {
  const { markup, styles } = stripForClassScan(html);
  const classes = new Set<string>();
  for (const match of markup.matchAll(/\sclass\s*=\s*(?:"([^"]*)"|'([^']*)')/g)) {
    for (const name of (match[1] ?? match[2] ?? "").split(/\s+/).filter(Boolean)) classes.add(name);
  }
  const ownClasses = new Set<string>();
  const ownVariables = new Set<string>();
  const variables = new Set<string>();
  for (const css of styles) {
    try {
      const root = postcss.parse(css);
      for (const name of classesDefinedIn(css, allClassesInSelector)) ownClasses.add(name);
      root.walkDecls((declaration) => {
        if (declaration.prop.startsWith("--")) ownVariables.add(declaration.prop);
        for (const match of declaration.value.matchAll(/var\(\s*(--[\w-]+)\s*\)/g)) variables.add(match[1]);
      });
    } catch {
      // A broken style block is reported by the browser; the class scan just skips it.
    }
  }
  for (const match of markup.matchAll(/style\s*=\s*"([^"]*)"/g)) {
    for (const prop of match[1].matchAll(/(--[\w-]+)\s*:/g)) ownVariables.add(prop[1]);
    for (const reference of match[1].matchAll(/var\(\s*(--[\w-]+)\s*\)/g)) variables.add(reference[1]);
  }
  return { classes: [...classes], ownClasses, variables: [...variables], ownVariables };
}

function customPropertiesIn(css: string): Set<string> {
  const names = new Set<string>();
  postcss.parse(css).walkDecls((declaration) => {
    if (declaration.prop.startsWith("--")) names.add(declaration.prop);
  });
  return names;
}

function readJson<T>(read: ReadFile, file: string, problems: string[]): T | undefined {
  const text = read(file);
  if (text === undefined) {
    problems.push(`${file} is missing.`);
    return undefined;
  }
  try {
    return JSON.parse(text) as T;
  } catch (error) {
    problems.push(`${file} is not valid JSON: ${(error as Error).message}`);
    return undefined;
  }
}

const GALLERY_STYLE = ` .g-wrap { width: min(1000px, calc(100% - 32px)); margin: 24px auto 60px; display: grid; gap: 18px; }
 .g-cover svg { display: block; width: 100%; height: auto; border-radius: 18px; border: 1px solid var(--line); }
 .g-intro { margin: 0; color: var(--muted); font-size: 0.875rem; }
 .g-head { margin: 22px 0 0; color: var(--imsda-navy); font-size: 1.3rem; font-weight: 700; }
 .g-card { border: 1px solid var(--line); border-radius: var(--radius-card); background: var(--card); overflow: hidden; box-shadow: var(--shadow-metric); }
 .g-meta { padding: 14px 18px; border-bottom: 1px solid var(--line); }
 .g-meta h3 { margin: 0; font-size: 1rem; font-weight: 700; }
 .g-meta p { margin: 4px 0; color: var(--muted); font-size: 0.875rem; }
 .g-meta a { color: var(--imsda-purple); font-size: 0.875rem; font-weight: 700; text-decoration: underline; }
 .g-meta code { font-size: 0.8rem; }
 .g-frame { background: var(--paper); overflow-x: auto; }`;

export function buildDesignSystem(read: ReadFile, listPreviews: () => string[]): BuildResult {
  const problems: string[] = [];
  const files = new Map<string, string>();
  const manifest = readJson<Manifest>(read, `${SOURCE_DIR}/parts.json`, problems);
  const notes = readJson<TokenNotes>(read, `${SOURCE_DIR}/token-notes.json`, problems);
  const previewBase = read(`${SOURCE_DIR}/preview-base.css`);
  const fontFaces = read(`${SOURCE_DIR}/fonts.css`);
  for (const [file, text] of [[`${SOURCE_DIR}/preview-base.css`, previewBase], [`${SOURCE_DIR}/fonts.css`, fontFaces]] as const) {
    if (text === undefined) problems.push(`${file} is missing.`);
  }
  if (!manifest || !notes || previewBase === undefined || fontFaces === undefined) return { files, problems, tokenValues: {} };

  // Every stylesheet the manifest or the notes point at.
  const cssFiles = new Set<string>([GLOBALS_FILE]);
  for (const part of manifest.parts) for (const spec of part.css) cssFiles.add(spec.file);
  for (const section of Object.values(notes)) {
    const tokens = (section as { tokens?: { file?: string }[] } | undefined)?.tokens;
    for (const token of Array.isArray(tokens) ? tokens : []) if (token.file) cssFiles.add(token.file);
  }
  const cssText: Record<string, string> = {};
  for (const file of cssFiles) {
    const text = read(file);
    if (text === undefined) problems.push(`${file} is missing (named in ${SOURCE_DIR}/parts.json or token-notes.json).`);
    else cssText[file] = text;
  }

  // Tokens.
  const tokenSources = [...new Set([GLOBALS_FILE, ...Object.keys(cssText).filter((file) => notesUse(notes, file))])];
  const tokens = buildTokens(notes, { files: cssText }, fontFaces, generatedHeader([...tokenSources, `${SOURCE_DIR}/token-notes.json`, `${SOURCE_DIR}/fonts.css`]));
  problems.push(...tokens.problems);
  const meta = (tokens.json.meta ?? {}) as Record<string, unknown>;
  tokens.json.meta = { generated: `${generatedHeader([...tokenSources, `${SOURCE_DIR}/token-notes.json`])} Edit those files, then run it again.`, ...meta };
  files.set(`${SYSTEM_DIR}/tokens.json`, `${JSON.stringify(tokens.json, null, 1)}\n`);
  files.set(`${SYSTEM_DIR}/tokens.css`, tokens.css);

  // bundle.css
  const byFile = new Map<string, CssSource[]>();
  for (const part of manifest.parts) {
    for (const spec of part.css) {
      const list = byFile.get(spec.file) ?? [];
      list.push({ part: part.name, file: spec.file, classes: spec.classes, selectors: spec.selectors, scopes: spec.scopes, all: spec.all });
      byFile.set(spec.file, list);
    }
  }
  const order = [PREFLIGHT_FILE, GLOBALS_FILE, ...[...byFile.keys()].filter((file) => file !== PREFLIGHT_FILE && file !== GLOBALS_FILE)].filter((file) => byFile.has(file));
  const hits = new Map<string, number>();
  const sections: string[] = [];
  for (const file of order) {
    const text = cssText[file];
    if (text === undefined) continue;
    const sources = byFile.get(file) ?? [];
    const result = extractCss(text, file, sources);
    problems.push(...result.problems);
    for (const [key, count] of result.hits) hits.set(key, (hits.get(key) ?? 0) + count);
    const partNames = [...new Set(sources.map((source) => source.part))];
    let block = result.css;
    if (LAYERED_FILES[file]) block = `@layer ${LAYERED_FILES[file]} {\n${block}\n}`;
    sections.push(`/* ===== ${file} (${partNames.join(", ")}) ===== */\n${block}`);
  }
  for (const part of manifest.parts) {
    for (const spec of part.css) {
      if (spec.all) continue;
      for (const name of spec.classes ?? []) {
        if (!hits.get(hitKey(part.name, "class", name))) problems.push(`parts.json: ${part.name} lists class "${name}" in ${spec.file}, but no rule there has it in its last compound.`);
      }
      for (const name of spec.scopes ?? []) {
        if (!hits.get(hitKey(part.name, "scope", name))) problems.push(`parts.json: ${part.name} lists scope "${name}" in ${spec.file}, but no rule there has it in a compound before the last.`);
      }
      for (const selector of spec.selectors ?? []) {
        if (!hits.get(hitKey(part.name, "selector", selector))) problems.push(`parts.json: ${part.name} lists selector "${selector}" in ${spec.file}, but no rule there has exactly that selector.`);
      }
    }
  }
  const bundleSources = [`${SOURCE_DIR}/preview-base.css`, ...order];
  const bundle = `/* ${generatedHeader(bundleSources)} */\n\n${previewBase.trim()}\n\n${sections.join("\n\n")}\n`;
  files.set(`${SYSTEM_DIR}/components/bundle.css`, bundle);

  // READMEs, previews and the gallery.
  const known = classesDefinedIn(bundle, allClassesInSelector);
  const definedVariables = new Set([...customPropertiesIn(tokens.css), ...customPropertiesIn(bundle)]);
  const cards: { group: string; name: string; html: string }[] = [];
  let cover = "";
  const partNames = new Set(manifest.parts.map((part) => part.name));
  for (const folder of listPreviews()) {
    if (!partNames.has(folder)) problems.push(`${SYSTEM_DIR}/components/${folder}/preview.html has no entry in ${SOURCE_DIR}/parts.json.`);
  }
  for (const part of manifest.parts) {
    if (part.preview === false) continue;
    const previewPath = `${SYSTEM_DIR}/components/${part.name}/preview.html`;
    const html = read(previewPath);
    if (html === undefined) {
      problems.push(`${previewPath} is missing.`);
      continue;
    }
    const preview = parsePreview(html);
    if (preview.height === undefined) problems.push(`${previewPath} needs a first line like <!-- @dsCard group="Actions" height=300 -->.`);
    if (part.group && preview.group !== part.group) problems.push(`${previewPath} says group "${preview.group ?? ""}" but parts.json says "${part.group}".`);
    if (part.group && !manifest.groups.includes(part.group)) problems.push(`parts.json: ${part.name} uses group "${part.group}", which is not in "groups".`);

    const usage = previewUsage(html);
    const missingClasses = usage.classes.filter((name) => !known.has(name) && !usage.ownClasses.has(name));
    for (const name of missingClasses) {
      problems.push(`${previewPath}: class "${name}" is in neither bundle.css nor the preview's own <style> (part ${part.name}).`);
    }
    for (const name of usage.variables) {
      if (!definedVariables.has(name) && !usage.ownVariables.has(name)) problems.push(`${previewPath}: ${name} is not defined by tokens.css, bundle.css or the preview (part ${part.name}).`);
    }

    let description = "";
    if (part.readme) {
      const source = read(part.readme);
      if (source === undefined) problems.push(`${part.readme} is missing (README source of ${part.name}).`);
      else {
        files.set(`${SYSTEM_DIR}/components/${part.name}/README.md`, `<!-- Generated by ${SYNC_COMMAND} from ${part.readme}. Edit that file, not this one. -->\n${source}`);
        description = firstParagraphHtml(source);
      }
    }
    const height = preview.height ?? 200;
    const previewBody = preview.body.split("../../assets/").join("assets/");
    if (!part.group) {
      cover = previewBody;
      continue;
    }
    cards.push({
      group: part.group,
      name: part.name,
      html: `<section class="g-card" id="${part.name}"><header class="g-meta"><h3>${part.name}</h3><p>${description}</p><a href="components/${part.name}/README.md">Usage rules</a></header><div class="g-frame" style="min-height:${height}px">${previewBody}\n</div></section>`,
    });
  }

  const body: string[] = [];
  for (const group of manifest.groups) {
    const inGroup = cards.filter((card) => card.group === group).sort((a, b) => a.name.localeCompare(b.name));
    if (inGroup.length === 0) continue;
    body.push(`<h2 class="g-head">${escapeHtml(group)}</h2>${inGroup.map((card) => card.html).join("")}`);
  }
  const gallery = `<!doctype html>
<!-- ${generatedHeader(["docs/design-system/components/*/preview.html", "docs/design-system/components/*/README.md source files", `${SOURCE_DIR}/parts.json`])} -->
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>IMAdventist design system</title>
<link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="components/bundle.css">
<style>
${GALLERY_STYLE}
</style></head>
<body><main class="g-wrap">
<div class="g-cover">${cover}
</div>
<p class="g-intro">Generated from components/*/preview.html. Static markup with fictional data, styled by the real CSS in components/bundle.css; see README.md for the rules.</p>
${body.join("")}
</main></body></html>
`;
  files.set(`${SYSTEM_DIR}/gallery.html`, gallery);

  return { files, problems: [...new Set(problems)], tokenValues: tokens.flat };
}

function notesUse(notes: TokenNotes, file: string): boolean {
  for (const section of Object.values(notes)) {
    const tokens = (section as { tokens?: { file?: string }[] } | undefined)?.tokens;
    if (Array.isArray(tokens) && tokens.some((token) => token.file === file)) return true;
  }
  return false;
}

/** Compare built files with what is on disk; each stale, missing or unexpected generated file is one line. */
export function compareWithDisk(built: Map<string, string>, read: ReadFile, existingReadmes: string[]): string[] {
  const lines: string[] = [];
  for (const [file, text] of built) {
    const onDisk = read(file);
    if (onDisk === undefined) lines.push(`missing: ${file}`);
    else if (onDisk !== text) lines.push(`stale: ${file}`);
  }
  for (const file of existingReadmes) {
    if (!built.has(file)) lines.push(`unexpected: ${file} is not generated by any part in ${SOURCE_DIR}/parts.json (delete it or add the part)`);
  }
  return lines;
}

export function diskReader(root: string): ReadFile {
  return (relativePath) => {
    try {
      return fs.readFileSync(path.join(root, relativePath), "utf8");
    } catch {
      return undefined;
    }
  };
}

export function listPreviewFolders(root: string): string[] {
  const dir = path.join(root, SYSTEM_DIR, "components");
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(dir, entry.name, "preview.html")))
    .map((entry) => entry.name)
    .sort();
}

export function listReadmeFiles(root: string): string[] {
  const dir = path.join(root, SYSTEM_DIR, "components");
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(dir, entry.name, "README.md")))
    .map((entry) => `${SYSTEM_DIR}/components/${entry.name}/README.md`)
    .sort();
}
